# Use the installed browser driver; do not install a second rendering stack.
BROWSER_SCRIPT = r"""
const fs = require('fs');
const config = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const { chromium } = require(config.playwright);
(async () => {
